/**
 * ProxiSpeak Proximity Event Adapter
 *
 * Decouples the frontend audio UI from the geolocation range-detection module.
 * Receives ENTER and EXIT events generated by the teammate's geolocation engine,
 * validates incoming payloads, and broadcasts them to listening React components.
 *
 * Communication mechanisms supported:
 * 1. Standard DOM CustomEvent: 'proxispeak:geo-event' on window
 * 2. Direct JavaScript callback subscription: subscribeToProximityEvents(handler)
 * 3. Direct programmatic dispatch: emitProximityEvent(event)
 */

const EVENT_NAME = 'proxispeak:geo-event';

// Active in-memory subscribers (for callback-based usage)
const subscribers = new Set();

/**
 * Validates the structure and types of an incoming proximity event payload.
 * Expected event shape:
 * {
 *   type: 'ENTER' | 'EXIT',
 *   audioId: string, // required
 *   title?: string,
 *   audioUrl?: string,
 *   description?: string,
 *   distance?: number // in meters or km
 * }
 *
 * @param {any} event
 * @returns {{ valid: boolean, error?: string, sanitized?: object }}
 */
export function validateProximityEvent(event) {
  if (!event || typeof event !== 'object') {
    return { valid: false, error: 'Event payload must be a non-null object' };
  }

  const { type, audioId } = event;

  if (!type || typeof type !== 'string') {
    return { valid: false, error: "Missing or invalid 'type'. Expected 'ENTER' or 'EXIT'" };
  }

  const normalizedType = type.trim().toUpperCase();
  if (normalizedType !== 'ENTER' && normalizedType !== 'EXIT') {
    return { valid: false, error: `Unsupported event type: "${type}". Expected 'ENTER' or 'EXIT'` };
  }

  if (!audioId || (typeof audioId !== 'string' && typeof audioId !== 'number')) {
    return { valid: false, error: "Missing or invalid 'audioId'. Must be a string or number" };
  }

  const sanitized = {
    type: normalizedType,
    audioId: String(audioId).trim(),
    title: typeof event.title === 'string' ? event.title.trim() : undefined,
    audioUrl: typeof event.audioUrl === 'string' ? event.audioUrl.trim() : undefined,
    description: typeof event.description === 'string' ? event.description.trim() : undefined,
    distance: typeof event.distance === 'number' && !isNaN(event.distance) ? event.distance : undefined,
    coordinates: event.coordinates && typeof event.coordinates === 'object' ? event.coordinates : undefined,
    timestamp: event.timestamp || Date.now()
  };

  return { valid: true, sanitized };
}

/**
 * Emits a proximity event to all listeners (both DOM CustomEvent and callback subscribers).
 * Called by the teammate's geolocation module or the mock test emitter.
 *
 * @param {object} event - { type, audioId, title, audioUrl, description, distance }
 * @returns {boolean} True if event was valid and dispatched
 */
export function emitProximityEvent(event) {
  const { valid, error, sanitized } = validateProximityEvent(event);

  if (!valid) {
    console.warn('[ProximityEventAdapter] Rejected invalid event:', error, event);
    return false;
  }

  // 1. Dispatch custom DOM event on window
  if (typeof window !== 'undefined') {
    const customEvent = new CustomEvent(EVENT_NAME, {
      detail: sanitized,
      bubbles: true,
      cancelable: true
    });
    window.dispatchEvent(customEvent);
  }

  // 2. Dispatch to registered programmatic subscribers
  subscribers.forEach((callback) => {
    try {
      callback(sanitized);
    } catch (err) {
      console.error('[ProximityEventAdapter] Error in subscriber callback:', err);
    }
  });

  return true;
}

/**
 * Subscribes a React component or service to proximity events.
 * Automatically listens to window CustomEvents as well as direct callback dispatches.
 *
 * @param {function(object): void} handler - Callback invoked with sanitized event
 * @returns {function(): void} Unsubscribe function for cleanup
 */
export function subscribeToProximityEvents(handler) {
  if (typeof handler !== 'function') {
    throw new Error('Subscriber handler must be a function');
  }

  // Register in memory set
  subscribers.add(handler);

  // Listen to DOM events
  const domListener = (e) => {
    if (e.detail) {
      handler(e.detail);
    }
  };

  if (typeof window !== 'undefined') {
    window.addEventListener(EVENT_NAME, domListener);
  }

  // Return teardown function
  return () => {
    subscribers.delete(handler);
    if (typeof window !== 'undefined') {
      window.removeEventListener(EVENT_NAME, domListener);
    }
  };
}

/**
 * Convenience helper to simulate an ENTER event for testing.
 */
export function simulateMockEnter(audioId, distance = 35, overrides = {}) {
  return emitProximityEvent({
    type: 'ENTER',
    audioId,
    distance,
    ...overrides
  });
}

/**
 * Convenience helper to simulate an EXIT event for testing.
 */
export function simulateMockExit(audioId) {
  return emitProximityEvent({
    type: 'EXIT',
    audioId
  });
}
